using DigitalEvidenceSystem.Web.Data; using DigitalEvidenceSystem.Web.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore;
namespace DigitalEvidenceSystem.Web.Pages.Cases; [Authorize] public sealed class CreateModel(EvidenceDbContext db, AuditService audit):PageModel { [BindProperty] public CaseFile Item {get;set;}=new(){Investigator="",OpenedOn=DateTime.Today}; public async Task OnGetAsync(){var year=DateTime.Today.Year;var count=await db.Cases.CountAsync(c=>c.OpenedOn.Year==year);Item.CaseNumber=$"CF-{year}-{count+1:D3}";} public async Task<IActionResult> OnPostAsync(){if(!ModelState.IsValid)return Page();if(await db.Cases.FindAsync(Item.Id)!=null||db.Cases.Any(x=>x.CaseNumber==Item.CaseNumber)){ModelState.AddModelError("Item.CaseNumber","That case number already exists. Please use the next available number.");return Page();}Item.CreatedAt=DateTime.Now; Item.UpdatedAt=DateTime.Now; db.Cases.Add(Item);await db.SaveChangesAsync();await audit.RecordAsync("Case created",$"{Item.CaseNumber} — {Item.Title}","Case",Item.Id.ToString());return RedirectToPage("Index");}}
